loorCount":"07 tầng nổi, 01 tầng bán hầm kỹ thuật","buildingHeight":28.5,"capacity":"200 giường bệnh nội trú, công suất phục vụ 600 lượt khám/ngày đêm","totalInvestment":385000000000,"appraisalItemCost":385000000000,"fundingSource":"Vốn Đầu tư công (Ngân sách tỉnh Điện Biên 60% + Ngân sách Trung ương hỗ trợ 40%)","costBreakdown":{"construction":210000000000,"equipment":82500000000,"management":6200000000,"consulting":14800000000,"others":36000000000,"contingency":35500000000},"executionPeriod":"2026 – 2028 (36 tháng)","startDate":"15/03/2026","completionDate":"31/12/2028","phases":"Giai đoạn 1 (2026-2027): Thi công khối nhà khám & điều trị 7 tầng; Giai đoạn 2 (2028): Khối truyền nhiễm, xử lý nước thải y tế & lắp đặt trang thiết bị.","standards":[{"code":"QCVN 01:2021/BXD","name":"Quy chuẩn kỹ thuật quốc gia về Quy hoạch xây dựng"},{"code":"QCVN 06:2022/BXD + SĐ 1:2023","name":"Quy chuẩn kỹ thuật quốc gia về An toàn cháy cho nhà và công trình"},{"code":"QCVN 02:2022/BXD","name":"Quy chuẩn kỹ thuật quốc gia về Số liệu điều kiện tự nhiên dùng trong xây dựng"},{"code":"TCVN 4470:2012","name":"Bệnh viện đa khoa - Tiêu chuẩn thiết kế"},{"code":"TCVN 9386:2012","name":"Thiết kế công trình chịu động đất (Địa bàn Điện Biên cấp VII)"},{"code":"QCVN 07:2023/BXD","name":"Quy chuẩn kỹ thuật quốc gia về các công trình Hạ tầng kỹ thuật"}],"legalDocs":[{"category":"Chủ trương đầu tư","docNumber":"1142/QĐ-UBND","docDate":"15/03/2026","issuer":"UBND tỉnh Điện Biên","description":"Quyết định phê duyệt chủ trương đầu tư dự án Bệnh viện Đa khoa Khu vực Mường Ảng","status":"da_xac_thuc"},{"category":"Quy hoạch chi tiết 1/500","docNumber":"540/QĐ-UBND","docDate":"10/05/2026","issuer":"UBND huyện Mường Ảng","description":"Quyết định phê duyệt Đồ án quy hoạch chi tiết xây dựng tỷ lệ 1/500 (Mã QH: QH-DB-MA-2026-05)","status":"da_xac_thuc"},{"category":"Thi tuyển kiến trúc","docNumber":"680/QĐ-SXD","docDate":"28/05/2026","issuer":"Sở Xây dựng Điện Biên","description":"Quyết định công nhận kết