 7.0%)","isPassed":true},{"name":"Hành lang an toàn đường bộ","designValue":"15.0m tính từ mép ngoài đất của đường","standardLimit":"Nghị định 11/2010/NĐ-CP (≥ 13.0m)","isPassed":true}],"fireSafety":{"agreementNumber":"183/PC07-CAĐB","agreementDate":"15/08/2026","agency":"Phòng Cảnh sát PCCC & CNCH — Công an Tỉnh Điện Biên","fireResistanceGrade":"Bậc I (Chịu lửa ≥ 150 phút)","evacuationDistance":"Không áp dụng đối với công trình tuyến giao thông","evacuationStaircases":"Không áp dụng","fireAccessRoad":"Đường giao thông nội bộ rộng 6.5m chạy bao quanh, khoảng cách đỗ xe chữa cháy đạt chuẩn","waterReserve":"Bể ngầm PCCC dung tích 250m³ kết hợp trạm bơm điện tử & máy phát diesel dự phòng 100%"},"costEvaluation":{"originalTotal":1292100000000,"appraisedTotal":1250000000000,"savingsTotal":42100000000,"items":[{"name":"1. Chi phí Bồi thường, Hỗ trợ & Tái định cư","originalValue":94500000000,"appraisedValue":87500000000,"difference":7000000000,"reason":"Loại trừ khối lượng hoa màu tính trùng lặp theo biên bản đối soát Ban ĐBGPMB huyện."},{"name":"2. Chi phí Xây dựng (Sau thẩm định)","originalValue":761250000000,"appraisedValue":725000000000,"difference":36250000000,"reason":"Áp dụng lại đơn giá vật liệu theo Thông báo giá Quý III/2026 của Liên sở SXD-STC Điện Biên."},{"name":"3. Chi phí Thiết bị & Công nghệ","originalValue":234000000000,"appraisedValue":225000000000,"difference":9000000000,"reason":"Thẩm định lại giá 3 báo giá cạnh tranh đối với thiết bị nhập khẩu chuyên dụng."},{"name":"4. Chi phí Quản lý Dự án","originalValue":31875000000,"appraisedValue":31250000000,"difference":625000000,"reason":"Định mức trích lập theo phụ lục Thông tư 12/2021/TT-BXD đối với dự án đầu tư công."},{"name":"5. Chi phí Tư vấn Đầu tư Xây dựng","originalValue":57937500000,"appraisedValue":56250000000,"difference":1687500000,"reason":"Chuẩn hóa định mức chi phí thẩm tra, lập hồ sơ mời thầu và khảo sát địa hình."},{"name":"6. Chi phí Dự phòng (Trượt giá & khối lượng)","originalValue":132500000000,"appraisedValue":125000000000,"difference":7500000000,"reason":"Cân đối tỷ lệ dự phòng theo thời gian thực hiện dự án 24-36 tháng."}]},"sample03Notice":{"docNumber":"183/SXD-QLXD","docDate":"Ngày 25 tháng 09 năm 2026","signerName":"Nguyễn Văn Hùng","signerTitle":"Phó Giám đốc Sở","submissionDoc":"Tờ trình số 42/TTr-0183","submissionDate":"2026-09-08","evaluationSummary":"Hồ sơ thiết kế cơ sở và tổng mức đầu tư dự án Nâng cấp, mở rộng Tuyến đường nối TP. Điện Biên Phủ đi Cửa khẩu Quốc tế Tây Trang tuân thủ quy chuẩn xây dựng hiện hành, phù hợp quy hoạch ngành và chỉ tiêu kinh tế kỹ thuật. Giải pháp kết cấu bảo đảm an toàn chịu lực, kháng chấn cấp VII và an toàn PCCC.","conclusion":"ĐỦ ĐIỀU KIỆN ĐỂ NGƯỜI QUYẾT ĐỊNH ĐẦU TƯ PHÊ DUYỆT BÁO CÁO NGHIÊN CỨU KHẢ THI THEO QUY ĐỊNH."},"permit":{"status":"cho_bo_sung","permitNumber":"183/GPXD-SXD","permitDate":"18/08/2026","checklistDocs":[{"name":"Đơn đề nghị cấp giấy phép xây dựng theo mẫu NĐ 217/2026","code":"DOC-01","status":"hop_le","note":"Đúng mẫu số 01 Phụ lục II"},{"name":"Giấy chứng nhận quyền sử dụng đất / Quyết định giao đất","code":"DOC-02","status":"hop_le","note":"UBND tỉnh cấp còn nguyên hiệu lực"},{"name":"Văn bản thẩm duyệt PCCC & Báo cáo ĐTM môi trường","code":"DOC-03","status":"hop_le","note":"Đã tích hợp đầy đủ số hiệu công văn"},{"name":"Hai bộ bản vẽ thiết kế xây dựng kèm Báo cáo kết quả thẩm tra","code":"DOC-04","status":"hop_le","note":"Đã đóng dấu thẩm tra của đơn vị tư vấn cấp I"},{"name":"Chứng chỉ năng lực hoạt động xây dựng của các tổ chức tham gia","code":"DOC-05","status":"hop_le","note":"Tra cứu CSDL Quốc gia hợp lệ 100%"}],"technicalConditions":{"allowedGroundArea":"25000 m²","allowedTotalFloorArea":"104167 m²","allowedStories":"08 tầng","allowedHeight":"32.5 m","specialRequirements":["Tuân thủ tuyệt đối chỉ giới đường đỏ và chỉ giới xây dựng đã định vị","Lắp đặt hệ thống quan trắc lún nghiêng và lưới an toàn che chắn bụi bẩn","Có biện pháp hoàn trả hiện trạng công trình ngầm hạ tầng kỹ thuật đô thị"]}},"inspection":{"groundBreakingConditions":[{"item":"Mặt bằng xây dựng đã được bàn giao mốc giới trên thực địa","status":"dat","verifyDate":"10/06/2026"},{"item":"Có Giấy phép xây dựng hoặc văn bản miễn giấy phép hợp lệ","status":"dat","verifyDate":"12/06/2026"},{"item":"Có thiết kế bản vẽ thi công đã được chủ đầu tư phê duyệt đóng dấu","status":"dat","verifyDate":"15/06/2026"},{"item":"Hợp đồng thi công xây dựng và hợp đồng bảo hiểm công trình","status":"dat","verifyDate":"18/06/2026"},{"item":"Thông báo ngày khởi công gửi Sở Xây dựng và UBND cấp huyện","status":"dat","verifyDate":"20/06/2026"}],"phaseInspections":[{"phaseName":"Nghiệm thu Giai đoạn Phần móng & Kết cấu ngầm","inspectDate":"15/07/2026","inspectTeam":"Đoàn Kiểm tra Sở Xây dựng phối hợp Ban QLDA","verdict":"chap_thuan","findings":"Chất lượng bê tông lót, cốt thép móng và kết quả nén mẫu R28 đạt thiết kế."},{"phaseName":"Nghiệm thu Giai đoạn Khung sàn bê tông cốt thép thân công trình","inspectDate":"22/08/2026","inspectTeam":"Tổ Giám sát Quản lý Xây dựng — SXD Điện Biên","verdict":"chap_thuan","findings":"Sai số kích thước hình học nằm trong phạm vi cho phép theo TCVN 4453:1995."},{"phaseName":"Nghiệm thu Hệ thống PCCC & Chạy thử liên động kỹ thuật","inspectDate":"10/09/2026","inspectTeam":"Sở Xây dựng, Cảnh sát PCCC & CNCH, Tư vấn Giám sát","verdict":"chap_thuan","findings":"Áp lực nước chữa cháy đầu lăng phun đạt 4.2 bar, hệ thống báo khói tự động nhạy bén."}],"finalNotice":{"noticeNumber":"183/TB-SXD","issueDate":"20/09/2026","result":"Chấp thuận kết quả nghiệm thu hoàn thành công trình của Chủ đầu tư đưa vào khai thác sử dụng.","recommendations":["Chủ đầu tư lưu trữ đầy đủ hồ sơ hoàn công công trình theo quy định","Thực hiện bảo trì công trình định kỳ theo quy trình đã được phê duyệt"]}},"auditLogs":[{"timestamp":"2026-09-08 08:30","actor":"Cổng Dịch vụ công Quốc gia","action":"Tiếp nhận hồ sơ điện tử","details":"Hồ sơ DA-2026-DB-0183 được đẩy tự động từ Cổng DVC Tân Dân tỉnh Điện Biên