e","note":"UBND tỉnh cấp còn nguyên hiệu lực"},{"name":"Văn bản thẩm duyệt PCCC & Báo cáo ĐTM môi trường","code":"DOC-03","status":"hop_le","note":"Đã tích hợp đầy đủ số hiệu công văn"},{"name":"Hai bộ bản vẽ thiết kế xây dựng kèm Báo cáo kết quả thẩm tra","code":"DOC-04","status":"hop_le","note":"Đã đóng dấu thẩm tra của đơn vị tư vấn cấp I"},{"name":"Chứng chỉ năng lực hoạt động xây dựng của các tổ chức tham gia","code":"DOC-05","status":"hop_le","note":"Tra cứu CSDL Quốc gia hợp lệ 100%"}],"technicalConditions":{"allowedGroundArea":"9600 m²","allowedTotalFloorArea":"40000 m²","allowedStories":"05 tầng","allowedHeight":"22.0 m","specialRequirements":["Tuân thủ tuyệt đối chỉ giới đường đỏ và chỉ giới xây dựng đã định vị","Lắp đặt hệ thống quan trắc lún nghiêng và lưới an toàn che chắn bụi bẩn","Có biện pháp hoàn trả hiện trạng công trình ngầm hạ tầng kỹ thuật đô thị"]}},"inspection":{"groundBreakingConditions":[{"item":"Mặt bằng xây dựng đã được bàn giao mốc giới trên thực địa","status":"dat","verifyDate":"10/06/2026"},{"item":"Có Giấy phép xây dựng hoặc văn bản miễn giấy phép hợp lệ","status":"dat","verifyDate":"12/06/2026"},{"item":"Có thiết kế bản vẽ thi công đã được chủ đầu tư phê duyệt đóng dấu","status":"dat","verifyDate":"15/06/2026"},{"item":"Hợp đồng thi công xây dựng và hợp đồng bảo hiểm công trình","status":"dat","verifyDate":"18/06/2026"},{"item":"Thông báo ngày khởi công gửi Sở Xây dựng và UBND cấp huyện","status":"dat","verifyDate":"20/06/2026"}],"phaseInspections":[{"phaseName":"Nghiệm thu Giai đoạn Phần móng & Kết cấu ngầm","inspectDate":"15/07/2026","inspectTeam":"Đoàn Kiểm tra Sở Xây dựng phối hợp Ban QLDA","verdict":"chap_thuan","findings":"Chất lượng bê tông lót, cốt thép móng và kết quả nén mẫu R28 đạt thiết kế."},{"phaseName":"Nghiệm thu Giai đoạn Khung sàn bê tông cốt thép thân công trình","inspectDate":"22/08/2026","inspectTeam":"Tổ Giám sát Quản lý Xây dựng — SXD Điện Biên","verdict":"chap_thuan","findings":"Sai số kích thước hình học nằm trong phạm vi cho phép theo TCVN 4453:1995."},{"phaseName":"Nghiệm thu Hệ thống PCCC & Chạy thử liên động kỹ thuật","inspectDate":"10/09/2026","inspectTeam":"Sở Xây dựng, Cảnh sát PCCC & CNCH, Tư vấn Giám sát","verdict":"chap_thuan","findings":"Áp lực nước chữa cháy đầu lăng phun đạt 4.2 bar, hệ thống báo khói tự động nhạy bén."}],"finalNotice":{"noticeNumber":"192/TB-SXD","issueDate":"20/09/2026","result":"Chấp thuận kết quả nghiệm thu hoàn thành công trình của Chủ đầu tư đưa vào khai thác sử dụng.","recommendations":["Chủ đầu tư lưu trữ đầy đủ hồ sơ hoàn công công trình theo quy định","Thực hiện bảo trì công trình định kỳ theo quy trình đã được phê duyệt"]}},"auditLogs":[{"timestamp":"2026-09-05 08:30","actor":"Cổng Dịch vụ công Quốc gia","action":"Tiếp nhận hồ sơ điện tử","details":"Hồ sơ DA-2026-DB-0192 được đẩy tự động từ Cổng DVC Tân Dân tỉnh Điện Biên sang hệ thống Thẩm định SXD.","badge":"info"},{"timestamp":"2026-09-05 08:35","actor":"AI Compliance Checker Engine","action":"Quét tự động Quy chuẩn & Hồ sơ pháp lý","details":"AI đối soát 18 danh mục quy chuẩn: Phát hiện 100% tài liệu hợp lệ, không có tiêu chuẩn hết hiệu lực.","badge":"audit"},{"timestamp":"2026-09-05 14:15","actor":"AI Cost Analysis Assistant","action":"Bóc tách chi phí & Đối soát định mức BXD","details":"Phát hiện chênh lệch đơn giá vật tư mác bê tông và vận chuyển đèo dốc. Đề xuất tiết giảm 21.800.000.000 VNĐ.","badge":"warning"},{"timestamp":"20/09/2026 10:20","actor":"KS. Trần Văn Hùng","action":"Chuyên viên chấp thuận đề xuất AI","details":"Chuyên viên thụ lý ghi nhận và tích hợp 100% kiến nghị của AI vào Báo cáo thẩm định chuyên môn.","badge":"success"},{"timestamp":"25/09/2026 16:00","actor":"Phó Giám đốc Sở — Nguyễn Văn Hùng","action":"Ký số văn bản điện tử Mẫu số 03","details":"Phê duyệt Thông báo kết quả thẩm định, cấp dấu mộc điện tử và đẩy kết quả sang Cổng DVC.","badge":"success"}]}}'::jsonb) on conflict (id) do nothing;
