026","code":"DOC-01","status":"hop_le","note":"Đúng mẫu số 01 Phụ lục II"},{"name":"Giấy chứng nhận quyền sử dụng đất / Quyết định giao đất","code":"DOC-02","status":"hop_le","note":"UBND tỉnh cấp còn nguyên hiệu lực"},{"name":"Văn bản thẩm duyệt PCCC & Báo cáo ĐTM môi trường","code":"DOC-03","status":"hop_le","note":"Đã tích hợp đầy đủ số hiệu công văn"},{"name":"Hai bộ bản vẽ thiết kế xây dựng kèm Báo cáo kết quả thẩm tra","code":"DOC-04","status":"hop_le","note":"Đã đóng dấu thẩm tra của đơn vị tư vấn cấp I"},{"name":"Chứng chỉ năng lực hoạt động xây dựng của các tổ chức tham gia","code":"DOC-05","status":"hop_le","note":"Tra cứu CSDL Quốc gia hợp lệ 100%"}],"technicalConditions":{"allowedGroundArea":"13000 m²","allowedTotalFloorArea":"54167 m²","allowedStories":"08 tầng","allowedHeight":"32.5 m","specialRequirements":["Tuân thủ tuyệt đối chỉ giới đường đỏ và chỉ giới xây dựng đã định vị","Lắp đặt hệ thống quan trắc lún nghiêng và lưới an toàn che chắn bụi bẩn","Có biện pháp hoàn trả hiện trạng công trình ngầm hạ tầng kỹ thuật đô thị"]}},"inspection":{"groundBreakingConditions":[{"item":"Mặt bằng xây dựng đã được bàn giao mốc giới trên thực địa","status":"dat","verifyDate":"10/06/2026"},{"item":"Có Giấy phép xây dựng hoặc văn bản miễn giấy phép hợp lệ","status":"dat","verifyDate":"12/06/2026"},{"item":"Có thiết kế bản vẽ thi công đã được chủ đầu tư phê duyệt đóng dấu","status":"dat","verifyDate":"15/06/2026"},{"item":"Hợp đồng thi công xây dựng và hợp đồng bảo hiểm công trình","status":"dat","verifyDate":"18/06/2026"},{"item":"Thông báo ngày khởi công gửi Sở Xây dựng và UBND cấp huyện","status":"dat","verifyDate":"20/06/2026"}],"phaseInspections":[{"phaseName":"Nghiệm thu Giai đoạn Phần móng & Kết cấu ngầm","inspectDate":"15/07/2026","inspectTeam":"Đoàn Kiểm tra Sở Xây dựng phối hợp Ban QLDA","verdict":"chap_thuan","findings":"Chất lượng bê tông lót, cốt thép móng và kết quả nén mẫu R28 đạt thiết kế."},{"phaseName":"Nghiệm thu Giai đoạn Khung sàn bê tông cốt thép