":1036000000,"reason":"Loại trừ khối lượng hoa màu tính trùng lặp theo biên bản đối soát Ban ĐBGPMB huyện."},{"name":"2. Chi phí Xây dựng (Sau thẩm định)","originalValue":112665000000,"appraisedValue":107300000000,"difference":5365000000,"reason":"Áp dụng lại đơn giá vật liệu theo Thông báo giá Quý III/2026 của Liên sở SXD-STC Điện Biên."},{"name":"3. Chi phí Thiết bị & Công nghệ","originalValue":34632000000,"appraisedValue":33300000000,"difference":1332000000,"reason":"Thẩm định lại giá 3 báo giá cạnh tranh đối với thiết bị nhập khẩu chuyên dụng."},{"name":"4. Chi phí Quản lý Dự án","originalValue":4717500000,"appraisedValue":4625000000,"difference":92500000,"reason":"Định mức trích lập theo phụ lục Thông tư 12/2021/TT-BXD đối với dự án đầu tư công."},{"name":"5. Chi phí Tư vấn Đầu tư Xây dựng","originalValue":8574750000,"appraisedValue":8325000000,"difference":249750000,"reason":"Chuẩn hóa định mức chi phí thẩm tra, lập hồ sơ mời thầu và khảo sát địa hình."},{"name":"6. Chi phí Dự phòng (Trượt giá & khối lượng)","originalValue":19610000000,"appraisedValue":18500000000,"difference":1110000000,"reason":"Cân đối tỷ lệ dự phòng theo thời gian thực hiện dự án 24-36 tháng."}]},"sample03Notice":{"docNumber":"207/SXD-QLXD","docDate":"Ngày 25 tháng 09 năm 2026","signerName":"Nguyễn Văn Hùng","signerTitle":"Phó Giám đốc Sở","submissionDoc":"Tờ trình số 42/TTr-0207","submissionDate":"2026-08-26","evaluationSummary":"Hồ sơ thiết kế cơ sở và tổng mức đầu tư dự án Trụ sở Ban Quản lý Khu Kinh tế Cửa khẩu và Trạm Kiểm soát Liên hợp Tây Trang tuân thủ quy chuẩn xây dựng hiện hành, phù hợp quy hoạch ngành và chỉ tiêu kinh tế kỹ thuật. Giải pháp kết cấu bảo đảm an toàn chịu lực, kháng chấn cấp VII và an toàn PCCC.","conclusion":"ĐỦ ĐIỀU KIỆN ĐỂ NGƯỜI QUYẾT ĐỊNH ĐẦU TƯ PHÊ DUYỆT BÁO CÁO NGHIÊN CỨU KHẢ THI THEO QUY ĐỊNH."},"permit":{"status":"cho_bo_sung","permitNumber":"207/GPXD-SXD","permitDate":"18/08/2026","checklistDocs":[{"name":"Đơn đề nghị cấp giấy phép xây dựng theo mẫu NĐ 217/2026","code":"DOC-01","status":"hop_le","note":"Đúng mẫu số 01 Phụ lục II"},{"name":"Giấy chứng nhận quyền sử dụng đất / Quyết định giao đất","code":"DOC-02","status":"hop_le","note":"UBND tỉnh cấp còn nguyên hiệu lực"},{"name":"Văn bản thẩm duyệt PCCC & Báo cáo ĐTM môi trường","code":"DOC-03","status":"hop_le","note":"Đã tích hợp đầy đủ số hiệu công văn"},{"name":"Hai bộ bản vẽ thiết kế xây dựng kèm Báo cáo kết quả thẩm tra","code":"DOC-04","status":"hop_le","note":"Đã đóng dấu thẩm tra của đơn vị tư vấn cấp I"},{"name":"Chứng chỉ năng lực hoạt động xây dựng của các tổ chức tham gia","code":"DOC-05","status":"hop_le","note":"Tra cứu CSDL Quốc gia hợp lệ 100%"}],"technicalConditions":{"allowedGroundArea":"3700 m²","allowedTotalFloorArea":"15417 m²","allowedStories":"05 tầng","allowedHeight":"22.0 m","specialRequirements":["Tuân thủ tuyệt đối chỉ giới đường đỏ và chỉ giới xây dựng đã định vị","Lắp đặt hệ thống quan trắc lún nghiêng và lưới an toàn che chắn bụi bẩn","Có biện pháp hoàn trả hiện trạng công trình ngầm hạ tầng kỹ thuật đô thị"]}},"inspection":{"groundBreakingConditions":[{"item":"Mặt bằng xây dựng đã được bàn giao mốc giới trên thực địa","status":"dat","verifyDate":"10/06/2026"},{"item":"Có Giấy phép xây dựng hoặc văn bản miễn giấy phép hợp lệ","status":"dat","verifyDate":"12/06/2026"},{"item":"Có thiết kế bản vẽ thi công đã được chủ đầu tư phê duyệt đóng dấu","status":"dat","verifyDate":"15/06/2026"},{"item":"Hợp đồng thi công xây dựng và hợp đồng bảo hiểm công trình","status":"dat","verifyDate":"18/06/2026"},{"item":"Thông báo ngày khởi công gửi Sở Xây dựng và UBND cấp huyện","status":"dat","verifyDate":"20/06/2026"}],"phaseInspections":[{"phaseName":"Nghiệm thu Giai đoạn Phần móng & Kết cấu ngầm","inspectDate":"15/07/2026","inspectTeam":"Đoàn Kiểm tra Sở Xây dựng phối hợp Ban QLDA","verdict":"chap_thuan","findings":"Chất lượng bê tông lót, cốt thép móng và kết quả nén mẫu R28 đạt thiết kế."},{"phaseName":"Nghiệm thu Giai đoạn Khung sàn bê tông cốt th